CREATE TABLE IF NOT EXISTS payment_methods (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,provider VARCHAR(100) NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,config_json JSON NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,KEY payment_method_enabled(enabled,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NULL,payment_method_id BIGINT UNSIGNED NULL,provider VARCHAR(100) NOT NULL,transaction_reference VARCHAR(190) NULL,provider_reference VARCHAR(190) NULL,amount DECIMAL(14,2) NOT NULL,currency VARCHAR(10) NOT NULL DEFAULT 'USD',status ENUM('pending','authorized','paid','failed','cancelled','refunded','partially_refunded') NOT NULL DEFAULT 'pending',failure_code VARCHAR(120) NULL,failure_message VARCHAR(500) NULL,paid_at TIMESTAMP NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY payment_tx_ref(transaction_reference),KEY payment_order(order_id,status),KEY payment_user(user_id,created_at),KEY payment_provider(provider,provider_reference)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_webhooks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(100) NOT NULL,event_id VARCHAR(190) NOT NULL,event_type VARCHAR(190) NULL,payload JSON NOT NULL,status ENUM('received','processed','ignored','failed') NOT NULL DEFAULT 'received',processed_at TIMESTAMP NULL,error_message VARCHAR(1000) NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,UNIQUE KEY webhook_event(provider,event_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payment_reconciliations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,transaction_id BIGINT UNSIGNED NOT NULL,provider_status VARCHAR(100) NULL,system_status VARCHAR(100) NULL,difference_amount DECIMAL(14,2) NOT NULL DEFAULT 0,status ENUM('matched','mismatch','pending') NOT NULL DEFAULT 'pending',checked_at TIMESTAMP NULL,notes TEXT NULL,created_at TIMESTAMP NULL,updated_at TIMESTAMP NULL,KEY reconciliation_status(status,checked_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
